#!/bin/sh
# Build the WebAssembly search (core.c) into core-wasm.js (base64: engine.js loads it synchronously in a worker and in Node).
# Then: node tools/check_wasm.js (the same results as the JS search)
cd "$(dirname "$0")/.."
clang --target=wasm32 -nostdlib -fno-builtin -O3 -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--allow-undefined -Wl,-z,stack-size=8388608 -Wl,--initial-memory=83886080 -o /tmp/agon-core.wasm core.c || exit 1
node -e "const b=require('fs').readFileSync('/tmp/agon-core.wasm');require('fs').writeFileSync('core-wasm.js','// generated by tools/build-core.sh from core.c — do not edit\nself.AG_WASM=\''+b.toString('base64')+'\';\n');console.log('core-wasm.js', b.length, 'bytes of wasm')"
# core_mt.wasm (2026-11-11): the same core for the threads of the page's pool (shared/mtengine.js; the lead engine.js?…&mt=1, the
# helpers mt-helper.js): -DMT — thread-local search state, one lockless table, Praline's Young Brothers Wait (shared/praline/)
clang --target=wasm32 -O3 -matomics -mbulk-memory -DMT -nostdlib -fno-builtin -w -Wl,--no-entry -Wl,--export-dynamic -Wl,--shared-memory -Wl,--import-memory -Wl,--max-memory=1073741824 -o core_mt.wasm core.c || exit 1
echo "core_mt.wasm $(wc -c < core_mt.wasm) bytes"
